import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
            B = []
            for _ in range(N):
                B.append(int(next(iterator)))
        except StopIteration:
            break

        D = [B[i] - A[i] for i in range(N)]

        possible = True
        for d in D:
            if d < 0:
                possible = False
                break

        if not possible:
            results.append("-1")
            continue

        if N == 0:
            results.append("0")
            continue

        ops = 0
        current_prefix_add = 0
        current_suffix_add = 0

        for i in range(N):
            needed = D[i]
            current_total = current_prefix_add + current_suffix_add

            diff = needed - current_total

            if diff > 0:
                if i == 0:
                    current_prefix_add += diff
                    ops += diff
                elif i == N - 1:
                    current_suffix_add += diff
                    ops += diff
                else:
                    if current_prefix_add > 0:
                        if current_prefix_add >= diff:
                            current_prefix_add -= diff
                            ops += diff
                        else:
                            ops += current_prefix_add
                            remaining = diff - current_prefix_add
                            current_prefix_add = 0
                            current_suffix_add += remaining
                            ops += remaining
                    else:
                        current_suffix_add += diff
                        ops += diff
            else:
                pass

        results.append(str(ops))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
